type AuthApiResponseLike = {
  code?: number | null;
  message?: string | null;
} | null | undefined;

export function authApiResponseSuccess(code?: number | null): boolean {
  return typeof code === 'number' &&
    (AUTH_API_RESPONSE_CONTRACT.successCodes as readonly number[]).includes(code);
}

export function authIsClientAppNotFoundCode(code?: number | null): boolean {
  return code === AUTH_API_RESPONSE_CONTRACT.clientAppNotFound.code;
}

export function authIsClientAppNotFoundMessage(message?: string | null): boolean {
  if (!message) {
    return false;
  }
  const normalized = message.toLowerCase();
  return normalized.includes(AUTH_API_RESPONSE_CONTRACT.clientAppNotFound.messageFragments.en) ||
    message.includes(AUTH_API_RESPONSE_CONTRACT.clientAppNotFound.messageFragments.zhHans);
}

export function authIsClientAppNotFoundResponse(response?: AuthApiResponseLike): boolean {
  return authIsClientAppNotFoundCode(response?.code) ||
    authIsClientAppNotFoundMessage(response?.message);
}

