export type ActrServiceEndpointConfig = {
  domain_name: string;
  port_info?: string | null;
};

export type ActrTomlConfig = {
  app_id: string;
  key_id: string;
  manufacturer: string;
  name: string;
  authority_services: readonly unknown[];
  signaling_services: readonly ActrServiceEndpointConfig[];
  stun_services: readonly ActrServiceEndpointConfig[];
  turn_services: readonly ActrServiceEndpointConfig[];
  realm_id: string;
};

export type ActrLockTomlConfig = {
  manufacturer: string;
  name: string;
};

function actrEndpointHost(endpoint: ActrServiceEndpointConfig): string {
  return `${endpoint.domain_name}${endpoint.port_info ? `:${endpoint.port_info}` : ''}`;
}

export function normalizeActrSignalingUrl(endpoint?: ActrServiceEndpointConfig | null): string {
  if (!endpoint) {
    return ACTR_CONFIG_CONTRACT.defaultSignalingUrl;
  }

  let url = `${actrEndpointHost(endpoint)}${ACTR_CONFIG_CONTRACT.signalingPath}`;
  if (!url.startsWith('ws')) {
    url = `wss://${url}`;
  }
  return url;
}

export function normalizeActrStunUrl(endpoint: ActrServiceEndpointConfig): string {
  let url = actrEndpointHost(endpoint);
  if (!url.startsWith('stun:')) {
    url = `stun:${url}`;
  }
  return url;
}

export function normalizeActrTurnUrl(endpoint: ActrServiceEndpointConfig): string {
  let url = actrEndpointHost(endpoint);
  if (!url.startsWith('turn:')) {
    url = `turn:${url}`;
  }
  return url;
}

export function generateActrToml(config: ActrTomlConfig): string {
  const signalingUrl = normalizeActrSignalingUrl(config.signaling_services?.[0]);
  const stunUrls = (config.stun_services || [])
    .map((service) => `"${normalizeActrStunUrl(service)}"`)
    .join(', ');
  const turnUrls = (config.turn_services || [])
    .map((service) => `"${normalizeActrTurnUrl(service)}"`)
    .join(', ');

  return `edition = 1
exports = []

[package]
name = "${ACTR_CONFIG_CONTRACT.package.name}"
description = "${ACTR_CONFIG_CONTRACT.package.description}"
authors = ["${ACTR_CONFIG_CONTRACT.package.author}"]
license = "${ACTR_CONFIG_CONTRACT.package.license}"
tags = ["${ACTR_CONFIG_CONTRACT.package.tags.dev}", "${ACTR_CONFIG_CONTRACT.package.tags.client}"]

[package.actr_type]
manufacturer = "${ACTR_CONFIG_CONTRACT.clientActrType.manufacturer}"
name = "${ACTR_CONFIG_CONTRACT.clientActrType.name}"

[dependencies]
${ACTR_CONFIG_CONTRACT.dependencyName} = { actr_type = "${config.manufacturer}+${config.name}" }

[system.signaling]
url = "${signalingUrl}"

[system.deployment]
realm_id = ${config.realm_id}

[system.discovery]
visible = true

[system.observability]
filter_level = "${ACTR_CONFIG_CONTRACT.observability.filterLevel}"
tracing_enabled = true
tracing_endpoint = "${ACTR_CONFIG_CONTRACT.observability.tracingEndpoint}"
tracing_service_name = "${ACTR_CONFIG_CONTRACT.package.name}"

[system.webrtc]
force_relay = false
stun_urls = [${stunUrls}]
turn_urls = [${turnUrls}]

[scripts]
dev = "${ACTR_CONFIG_CONTRACT.scripts.dev}"
test = "${ACTR_CONFIG_CONTRACT.scripts.test}"

[acl]

[[acl.rules]]
permission = "${ACTR_CONFIG_CONTRACT.acl.allow}"
types = ["${config.manufacturer}+${config.name}"]
`;
}

